import unittest

class Behavior(unittest.TestCase):
    def test_contract(self):
        from seats import seat_at
        labels = ['A0','A1','A2','B0','B1','B2']
        before = labels[:]
        for row in range(2):
            for col in range(3):
                self.assertEqual(seat_at(labels, 3, row, col), before[row*3+col])
        self.assertEqual(labels, before)
        self.assertEqual(seat_at(['X','Y','Z'], 1, 2, 0), 'Z')
        self.assertEqual(seat_at(['X','Y','Z'], 3, 0, 2), 'Z')
        self.assertEqual(seat_at(['only'], 1, 0, 0), 'only')

if __name__ == "__main__":
    unittest.main()
